const BAC_OPTIONS = [1, 2, 3];
const BAC_BASE = 2;

function bacEligible(specs) {
  const r = (specs.find(x => x[0] === 'Reconstitution') || [])[1] || '';
  return /^(All vials: )?2\.0ml bac water/.test(r);
}

function fmtUnits(u) {
  if (u >= 10) return String(Math.round(u));
  const r = Math.round(u * 10) / 10;
  return (r % 1 === 0) ? String(r) : r.toFixed(1);
}
function fmtMl(ml) {
  if (ml >= 0.1) return ml.toFixed(2);
  return String(parseFloat(ml.toFixed(3)));
}
function toBase(n, unit) {
  unit = unit.toLowerCase();
  if (unit === 'mcg') return { v: n / 1000, u: 'mg' };
  if (unit === 'iu') return { v: n, u: 'iu' };
  return { v: n, u: 'mg' };
}
function parseAmounts(str) {
  const m = String(str).replace(/,/g, '').match(/([\d.]+)(?:\s*[–-]\s*([\d.]+))?\s*(mcg|mg|IU)\b/i);
  if (!m) return null;
  const a = toBase(parseFloat(m[1]), m[3]);
  const out = { u: a.u, vals: [a.v] };
  if (m[2]) out.vals.push(toBase(parseFloat(m[2]), m[3]).v);
  return out;
}
const DRAW_RE = /^([\d.]+)(?:[–-]([\d.]+))? units · ([\d.]+)(?:[–-]([\d.]+))?ml$/;

// Per-injection dose for a row: an "Xmg × N injections" cell wins, else the first cell with an amount.
function rowDose(row) {
  for (let i = 1; i < row.length; i++) {
    const m = String(row[i]).match(/([\d.]+)\s*(mcg|mg|IU)\s*×\s*\d+\s*injections/i);
    if (m) { const a = toBase(parseFloat(m[1]), m[2]); return { u: a.u, vals: [a.v] }; }
  }
  for (let i = 1; i < row.length; i++) {
    if (DRAW_RE.test(row[i])) continue;
    const a = parseAmounts(row[i]);
    if (a) return a;
  }
  return null;
}

// Rescale a 2ml draw table to w ml of bac water.
function scaleTable(t, w, vialSpec) {
  if (w === BAC_BASE) return t;
  const f = w / BAC_BASE;
  const nCols = t.headers.length;
  const colC = {};
  for (let c = 0; c < nCols; c++) {
    let best = null;
    t.rows.forEach(r => {
      const m = String(r[c]).match(DRAW_RE); if (!m) return;
      const d = rowDose(r); if (!d) return;
      const units = parseFloat(m[2] || m[1]);
      const dose = d.vals[d.vals.length - 1];
      if (dose > 0 && (!best || units > best.units)) best = { units, c: units / dose, u: d.u };
    });
    if (!best) continue;
    // Prefer the exact vial strength when the header or spec names it and it agrees with the table.
    const hv = parseAmounts((String(t.headers[c]).match(/\(([^)]*vial)\)/) || [])[1] || '') || parseAmounts(vialSpec || '');
    if (hv && hv.u === best.u && hv.vals[0] > 0) {
      const exact = 100 * BAC_BASE / hv.vals[0];
      if (Math.abs(exact - best.c) / exact < 0.1) best.c = exact;
    }
    colC[c] = best;
  }
  const rows = t.rows.map(r => r.map((cell, c) => {
    const m = String(cell).match(DRAW_RE);
    if (!m) return cell;
    const d = rowDose(r);
    const k = colC[c];
    let us;
    if (k && d && d.u === k.u) {
      const nums = (m[2] && d.vals.length === 2) ? d.vals : [d.vals[d.vals.length - 1]];
      us = nums.map(v => v * k.c * f);
    } else {
      us = [parseFloat(m[1])].concat(m[2] ? [parseFloat(m[2])] : []).map(v => v * f);
    }
    const shown = us.map(fmtUnits);
    const uStr = shown.join('–');
    const mlStr = shown.map(u => fmtMl(parseFloat(u) / 100)).join('–');
    return uStr + (uStr === '1' ? ' unit · ' : ' units · ') + mlStr + 'ml';
  }));
  return { headers: t.headers, rows };
}

function scaleSpec(label, value, w) {
  if (label !== 'Reconstitution' || w === BAC_BASE) return value;
  return value
    .replace(/2\.0ml bac water/, w.toFixed(1) + 'ml bac water')
    .replace(/· 200 units/, '· ' + (w * 100) + ' units')
    .replace(/([\d,]+)IU\/ml/, (all, n) => Math.round(parseFloat(n.replace(/,/g, '')) * BAC_BASE / w) + 'IU/ml');
}

